select i.* , c1.companyname as relatedcompanyname, (SELECT description FROM master WHERE masterid = relationshiptypeid) AS relationshiptypedesc, c1.companytypeid as relatedcompanyid,(SELECT description FROM master WHERE masterid = relatedcompanyid) AS relatedcompanytype, c2.companyname as primarycompanyname , c2.companytypeid as primarycompanytypeid, (SELECT description FROM master WHERE masterid = primarycompanytypeid) AS primarycompanytype from investor i inner join company c1 on c1.companyid = i.relativecompanyid inner join company c2 on c2.companyid = i.targetcompanyid 